// The design tokens (design/tokens.json) as CSS custom properties, generated by Style Dictionary 5 in memory, as
// design/README.md describes: the file read as it is (DTCG), transform group `css`, format `css/variables`. Nothing
// generated is written to the repository; the UI imports it as `virtual:prq/tokens.css` (tokensPlugin), and the
// favicon script reads the resolved colors from here.

import { fileURLToPath } from "node:url";

import StyleDictionary from "style-dictionary";
import type { Plugin } from "vite";

const TOKENS_FILE = fileURLToPath(new URL("../../../design/tokens.json", import.meta.url));

const VIRTUAL_ID = "virtual:prq/tokens.css";
// The \0 prefix keeps other plugins off the module; the .css suffix sends it through Vite's CSS pipeline.
const RESOLVED_ID = `\0${VIRTUAL_ID}`;

function dictionary(): StyleDictionary {
  return new StyleDictionary({
    source: [TOKENS_FILE],
    usesDtcg: true,
    // A typography token is a `font` shorthand, which cannot hold letter spacing; Style Dictionary warns about it on
    // every build, and the value is 0 in every text style (design/README.md).
    log: { warnings: "disabled", verbosity: "silent" },
    // No "Do not edit" header: nothing generated is written to a file. The custom properties go on :root, in the
    // `tokens` cascade layer.
    platforms: {
      css: {
        transformGroup: "css",
        files: [
          {
            format: "css/variables",
            destination: "tokens.css",
            options: { showFileHeader: false, selector: ["@layer tokens", ":root"] },
          },
        ],
      },
    },
  });
}

// The custom properties on :root, in the `tokens` cascade layer.
export async function tokensCss(): Promise<string> {
  const [file] = await dictionary().formatPlatform("css");
  if (typeof file?.output !== "string") {
    throw new Error("Style Dictionary produced no CSS for design/tokens.json");
  }
  return file.output;
}

// Each token's CSS value by its path (`color.accent.emphasis` → `#1f6feb`), as the custom properties hold it.
export async function tokenValues(): Promise<Map<string, string>> {
  const { allTokens } = await dictionary().getPlatformTokens("css");
  return new Map(allTokens.map((token) => [token.path.join("."), String(token.$value ?? token.value)]));
}

// Serves `virtual:prq/tokens.css`, regenerated when design/tokens.json changes in dev.
export function tokensPlugin(): Plugin {
  return {
    name: "prq:tokens",
    resolveId(id) {
      return id === VIRTUAL_ID ? RESOLVED_ID : undefined;
    },
    async load(id) {
      if (id !== RESOLVED_ID) {
        return undefined;
      }
      this.addWatchFile(TOKENS_FILE);
      return tokensCss();
    },
  };
}
